+// Snapshot compatibility with engine/intraday_flow.classify_entry_timing.
+// This does not persist episodes or infer an observed historical trigger.
+function timingFiniteNumber(value) {
+  if (typeof value !== 'number' && typeof value !== 'string') return null;
+  if (typeof value === 'string' && !/^[+-]?(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?$/.test(value.trim())) return null;
+  var number = Number(value);
+  return Number.isFinite(number) ? number : null;
+}
+function classifyEntryTiming(entryStatus, currentPrice, chaseAbove) {
+  function out(state, reason, started) {
+    return {state:state, reason:reason, get_ready_eligible:state==='forming', already_started:started};
+  }
+  if (entryStatus == null || (typeof entryStatus === 'string' && !entryStatus.trim())) {
+    return out('unknown','status_missing',null);
+  }
+  if (typeof entryStatus !== 'string') return out('unknown','status_unknown',null);
+  var status = entryStatus.trim().toLowerCase();
+  var forming = ['buy_soon','await_confluence','watch','bounce_wait'].indexOf(status) >= 0;
+  var active = ['buy_now','partial'].indexOf(status) >= 0;
+  var moving = ['hold','extended','wait_pullback','topping'].indexOf(status) >= 0;
+  var failed = ['exit','avoid','blocked'].indexOf(status) >= 0;
+  if (failed) return out('failed_or_blocked','status_failed_or_blocked',null);
+  var price = timingFiniteNumber(currentPrice), chase = timingFiniteNumber(chaseAbove);
+  if ((forming || active || moving) && price != null && chase != null && chase > 0 && price > chase) {
+    return out('already_moving','above_chase',true);
+  }
+  if (forming) return out('forming','status_forming',false);
+  if (active) return out('active_window','status_active_window',true);
+  if (moving) return out('already_moving','status_already_moving',true);
+  return out('unknown','status_unknown',null);
+}
